{
  "technical_and_design_decisions": [
    "Capabilities framework will use three separate maps in channel config (root, application, orderer) to support version-based feature gating.",
    "Unsupported capabilities will cause the binary to crash immediately to ensure data integrity.",
    "Read-Your-Writes (RYW) will be enabled via a new API method GetTrxState on the chaincode stub.",
    "MSPConfig will be refactored from a concrete type to an interface to allow custom configurations.",
    "Chaincode singletons will be removed using dependency injection to improve testability.",
    "Test configuration files (peer core.yaml, orderer.yaml) will be generated from a World config struct during test setup.",
    "Validation parameters interface will return default signature policy requiring majority of orgs for '+lifecycle' chaincode.",
    "All changes will be implemented using existing protobuf definitions and Hyperledger Fabric coding standards."
  ],
  "assumptions": [
    "The developer is experienced with the Hyperledger Fabric codebase and build environment.",
    "Effort estimates are based on a single developer working full-time; no parallel activities.",
    "Testing includes unit tests, integration tests, and functional verification for each feature.",
    "The video for U3 (adding organizations) is a development deliverable; 20 hours allocated for video creation and editing.",
    "The capabilities framework design document is accepted and no major rework is needed.",
    "All user stories are independent unless noted (U6 is prerequisite for U8 lifecycle work, but effort is estimated separately).",
    "Development environment is already set up with all dependencies (Go, Docker, etc.).",
    "Estimates are in work-hours and assume focused, uninterrupted work."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Capabilities Framework Implementation",
      "activity_description": "Design and implement the capabilities framework: add capabilities maps to channel config (root, application, orderer), implement capability checking logic, crash on unsupported capabilities, integrate with orderer and peer code, and write tests.",
      "most_likely_effort": 120
    },
    {
      "activity_id": "A2",
      "activity_name": "Read-Your-Writes API (GetTrxState)",
      "activity_description": "Design, implement, and test the GetTrxState method on the chaincode stub interface to allow chaincode developers to read updated keys during a transaction.",
      "most_likely_effort": 30
    },
    {
      "activity_id": "A3",
      "activity_name": "Dynamic Organization Addition Support and Video",
      "activity_description": "Develop or enhance tooling/scripts to add organizations to a running network (if needed) and produce a step-by-step video tutorial demonstrating the process.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A4",
      "activity_name": "CouchDB Query Performance Metrics",
      "activity_description": "Implement performance monitoring for CouchDB state database queries by adding metrics (e.g., latency, throughput) and logging, with associated tests.",
      "most_likely_effort": 30
    },
    {
      "activity_id": "A5",
      "activity_name": "MSPConfig Interface Refactoring",
      "activity_description": "Refactor MSPConfig from a concrete type to an interface, updating all usages in the codebase, and verify with tests.",
      "most_likely_effort": 30
    },
    {
      "activity_id": "A6",
      "activity_name": "Remove Chaincode Singletons",
      "activity_description": "Identify and remove chaincode singletons (e.g., global state) using dependency injection, refactor affected code, and ensure tests pass.",
      "most_likely_effort": 50
    },
    {
      "activity_id": "A7",
      "activity_name": "Test Config Generation from World Config",
      "activity_description": "Implement test infrastructure to generate peer core.yaml and orderer.yaml configuration files from a World config struct, enabling reproducible test setups.",
      "most_likely_effort": 25
    },
    {
      "activity_id": "A8",
      "activity_name": "Validation Parameters Interface for Lifecycle",
      "activity_description": "Implement the interface returning validation parameters for chaincode, including a special default signature policy for '+lifecycle' requiring majority of orgs, and integrate with new lifecycle.",
      "most_likely_effort": 35
    }
  ],
  "reported_total": {
    "most_likely_effort": 360
  }
}

